// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createVisit, updateVisit, getVisit } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:9966");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const visitsPostResponse = await createVisit(client, URL_localhost, "2026-08-01", "duration persistence probe", 45, 7);
    expect(getResponseValue(visitsPostResponse, "id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(visitsPostResponse, "date"), 'date').toBe("2026-08-01");
    expect(getResponseValue(visitsPostResponse, "description"), 'description').toBe("duration persistence probe");
    expect(getResponseValue(visitsPostResponse, "petId"), 'petId').toBe(7);
    expect(getResponseValue(visitsPostResponse, "durationMinutes"), 'durationMinutes').toBe(45);

    const visitsVisitsPutResponse = await updateVisit(client, URL_localhost, getResponseValue(visitsPostResponse, "id"), "2026-08-01", "duration persistence probe", 90);

    const visitsVisitsGetResponse = await getVisit(client, URL_localhost, getResponseValue(visitsPostResponse, "id"));
    expect(getResponseValue(visitsVisitsGetResponse, "id"), 'id').toBe(getResponseValue(visitsPostResponse, "id"));
    expect(getResponseValue(visitsVisitsGetResponse, "date"), 'date').toBe("2026-08-01");
    expect(getResponseValue(visitsVisitsGetResponse, "description"), 'description').toBe("duration persistence probe");
    expect(getResponseValue(visitsVisitsGetResponse, "petId"), 'petId').toBe(7);
    expect(getResponseValue(visitsVisitsGetResponse, "durationMinutes"), 'durationMinutes').toBe(90);
});
